WITH with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM payments), sessions_payments AS (SELECT id, order_id, method, amount, paid_at, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT method, ROUND(AVG(amount), 2) AS avg_amount, SIZE(COLLECT_SET(method)) AS num_methods, ROUND(AVG(burst_id), 2) AS avg_burst_id, MAX(paid_at) AS ended_at, COUNT(DISTINCT order_id) AS distinct_order_ids, COUNT(*) FILTER (WHERE method = 'promptpay') AS promptpay_rows FROM sessions_payments GROUP BY 1 HAVING COUNT(DISTINCT order_id) < 1000 ORDER BY distinct_order_ids DESC;
